      "level": 7,
      "parent": null,
      "ja": "帯電像を用いる電子写真法用の装置（Ｇ０３Ｇ１６／００，Ｇ０３Ｇ１７／００が優先；｛データ処理装置のためのゼログラフィープリンタそれ自体Ｇ０６Ｋ１５／１４｝）注．このグループはそれ自体がこのグループに分類される装置の使用，または取扱いによって特徴づけられる限り処理法も包含する．｛注．グループＧ０３Ｇ１５／００Ｆ(ＥＣＬＡ)，Ｇ０３Ｇ１５／００Ｇ(ＥＣＬＡ)，Ｇ０３Ｇ１５／００Ｊ(ＥＣＬＡ)は，より一般的なグループ，例．Ｇ０３Ｂ，　Ｂ４１，Ｂ６５Ｈ，に分類可能であるが，Ｇ０３Ｇと関連して記述される，細部に関する文献を主として包含する．｝",
