    "G03G16/00": {
      "code": "G03G16/00",
      "level": 7,
      "parent": null,
      "ja": "熱可塑性樹脂層の変形を利用する電子写真法（表面変形画像のための層Ｇ０３Ｇ５／０２２）；そのための装置　｛（熱可塑性記憶効果をもつ可塑性物の成形Ｂ２９Ｃ６１／００；熱可塑性要素を用いるデジタル記憶Ｇ１１Ｃ１１／４６；変形可能な熱可塑性記憶媒体を用いるテレビジョン信号記録Ｈ０４Ｎ５／８２）｝",
      "en": "Electrographic processes using deformation of thermoplastic layers (layers for surface-deformation imaging G03G5/022); Apparatus therefor {(shaping of plastic objects with thermoplastic memory effect B29C61/00; digital stores using thermoplastic elements G11C11/46; television signal recording using deformable thermoplastic recording medium H04N5/82)}",
      "count": 285,
      "ipcCode": "G03G16/00",
      "coreCode": "G03G16/00",
      "note": "",
      "sourceFile": "cpc_G03G.txt",
      "kind": "cpc"
    },
    "G03G17/00": {
      "code": "G03G17/00",
      "level": 7,
      "parent": null,
      "ja": "帯電像以外の像を用いる電子写真方式，例．導電性像；泳動を含む方式，例．光電気泳動，光電子ソログラフィー；選択転写を含む方式，例．電子写真粘着方式；本来そのような単一方式を含む装置",
      "en": "Electrographic processes using patterns other than charge patterns, e.g. an electric conductivity pattern; Processes involving a migration, e.g. photoelectrophoresis, photoelectrosolography; Processes involving a selective transfer, e.g. electrophoto-adhesive processes; Apparatus essentially involving a single such process",
      "count": 232,
      "ipcCode": "G03G17/00",
      "coreCode": "G03G17/00",
      "note": "",
      "sourceFile": "cpc_G03G.txt",
      "kind": "cpc"
    },
