    "G03G2221/0005": {
      "code": "G03G2221/0005",
      "level": 8,
      "parent": "G03G2221/00",
      "ja": "残留トナーのクリーニング<br><br><u>注</u><br> <br>グループＧ０３Ｇ２２２１／０００５およびそのサブグループのインデキシングコードは＋の記号により先行される付加記号および関連する付加文字が追記され得る．インデキシングコードの意味は下記の通りである<br>＋Ａは現像装置により実行されるもの（いわゆるクリーナレス）<br>＋Ｂは別々の専用クリーニング装置により実行されるもの<br>＋Ｂ１は磁気ブラシを用いるもの<br>＋Ｂ２は機械的手段を用いるもの（粉末をも用いるもの）<br>＋Ｂ２Ｃは磁気的保持体を持つもの<br>＋Ｂ２Ｄは静電気保持体を持つもの（交流電圧をも用いるもの）<br>＋Ｂ３磁気手段を用いるもの（＋Ｂ１にあるような磁気ブラシでないもの；＋Ｂ２Ｃが優先）<br>＋Ｂ３Ｃは静電気保持体を持つもの（交流電圧をも用いるもの）<br>＋Ｂ４は静電気手段のみを用いるもの<br>＋Ｂ４Ｃは交流を持つもの<br>＋Ｂ４Ｄは直流のみのもの<br>＋Ｂ５は吸引または空気圧を含むもの<br>＋Ｃはクリーニング作用が行われることを高めるためのプレクリーニング処理<br>＋Ｃ１電極でトナーを放電するもの（コロナまたは類似のもの）<br>＋Ｃ１Ｄ交流を持つもの<br>＋Ｃ１Ｅ直流のみを持つもの<br>＋Ｃ２ランプで放電するもの（通常残留トナーがより容易に取り除かれるよう，光導電体を中和するもの）<br>＋Ｃ３は残留トナーを再配布するための機械的手段（磁気ブラシをも用いるもの）<br>＋Ｃ３Ｃは同時に光電性部材の主帯電装置として作動するもの<br>＋Ｃ３Ｄは磁気的保持体を持つもの<br>＋Ｃ３Ｅは静電気保持体を持つもの<br>＋Ｃ３Ｅ１は交流を含むもの<br>＋Ｃ３Ｐは複数の連続する機械的手段<br>＋Ｃ４は磁気的手段<br>＋Ｃ４Ｄは静電気保持体を持つもの（交流電圧も）<br>＋Ｃ５は静電気手段（＋Ｃ１の中のように帯電しないもの）<br>＋Ｃ５Ｄは交流を持つもの<br>＋Ｃ５Ｅは直流のみを持つもの<br>",
      "en": "Cleaning of residual toner",
      "count": 832,
      "ipcCode": "CPCONLY",
      "coreCode": "G03G2221/0005",
      "note": "",
      "sourceFile": "cpc_G03G.txt",
      "kind": "cpc"
    },
